from sys import stdin

def solve():
	ans = 0
	c = int(input().strip())
	for i in range(c):
		(ni, mi) = map(int, input().strip().split(' '))
		ans ^= (ni + mi - 2) % 3
	if ans:
		return 'MasterChef'
	else:
		return 'Football'
for _ in range(int(input().strip())):
	print(solve())
